import{_ as s,o as i,c as t,a3 as r,j as e,a}from"./chunks/framework.z_KJ15Ep.js";const u="/bilder/unterricht-kataloge/tutorials-hsu-fach-anlegenpng.png",h="/bilder/unterricht-kataloge/tutorials-hsu-laufbahninfo.png",g="/bilder/unterricht-kataloge/tutorials-hsu-leistungsdaten.png",k=JSON.parse('{"title":"Herkunftssprachlichen Unterricht und Sprachprüfungen erfassen","description":"","frontmatter":{"title":"Herkunftssprachlichen Unterricht und Sprachprüfungen erfassen","source_pageid":1438,"source_revision":5776},"headers":[],"relativePath":"schild3/unterricht-kataloge/herkunftssprachlicher-unterricht-tutorial.md","filePath":"schild3/unterricht-kataloge/herkunftssprachlicher-unterricht-tutorial.md"}'),l={name:"schild3/unterricht-kataloge/herkunftssprachlicher-unterricht-tutorial.md"};function c(d,n,o,p,f,m){return i(),t("div",null,[...n[0]||(n[0]=[r(`<h1 id="herkunftssprachlichen-unterricht-und-sprachprufungen-erfassen" tabindex="-1">Herkunftssprachlichen Unterricht und Sprachprüfungen erfassen <a class="header-anchor" href="#herkunftssprachlichen-unterricht-und-sprachprufungen-erfassen" aria-label="Permalink to &quot;Herkunftssprachlichen Unterricht und Sprachprüfungen erfassen&quot;">​</a></h1><p>Bereiten Sie Fächer, Sprachenfolge und Leistungsdaten für herkunftssprachlichen Unterricht vor. Beachten Sie die unterschiedlichen Einträge und Ausgaben nach Schulstufe und Zeugnisart.</p><h2 id="herkunftssprachlicher-unterricht" tabindex="-1">Herkunftssprachlicher Unterricht <a class="header-anchor" href="#herkunftssprachlicher-unterricht" aria-label="Permalink to &quot;Herkunftssprachlicher Unterricht&quot;">​</a></h2><p><strong>Zielgruppe:</strong> Schülerinnen und Schülern mit internationaler Familiengeschichte, die ganz normal am Regelunterricht teilnehmen.</p><p><strong>Teilnahmepflicht:</strong> Die Anmeldung verpflichtet zur regelmäßigen Teilnahme. Eine Abmeldung ist nur zum Schuljahresende für das kommende Schuljahr möglich.</p><p><strong>Sprachprüfung:</strong> Am Ende des Bildungsgangs in der Sekundarstufe I wird die Prüfung auf der Anspruchsebene des angestrebten Abschlusses abgelegt.</p><ul><li>Nach <a href="https://bass.schule.nrw/12691.htm" target="_blank" rel="noreferrer">§ 5 Absatz 3 APO-S I</a> kann eine mindestens gute Prüfungsleistung bei Abschlüssen <strong>und der Berechtigung zum Besuch der Oberstufe nach §§ 40 bis 43</strong> eine Minderleistung in einer Fremdsprache ersetzen. Das gilt nicht bei „ungenügend“. Die ersetzende Note darf keine weitere Minderleistung ausgleichen. Die frühere pauschale Ausnahme für MSA-Q gilt seit 1. August 2026 nicht mehr.</li><li>Diese besondere Regel zur Abschluss- und Berechtigungsvergabe ist kein allgemeiner Ausgleich bei jeder Versetzung. Eine Feststellungsprüfung als Fremdsprachenersatz nach § 5 Absatz 4 ist ein anderes Verfahren.</li><li>Mit bestandener HSU-Sprachprüfung auf MSA-Niveau kann die Sprache in der Oberstufe als fortgeführte Fremdsprache belegt werden, wenn sie angeboten wird; bloße Unterrichtsteilnahme genügt hierfür nicht. Siehe <a href="https://bass.schule.nrw/16253.htm" target="_blank" rel="noreferrer">BASS 13-61 Nr. 2</a>.</li><li>Die Belegung einer fortgeführten Herkunftssprache und die Erfüllung der Pflicht zur zweiten Fremdsprache sind getrennt zu prüfen. Maßgeblich sind <a href="https://bass.schule.nrw/9607.htm" target="_blank" rel="noreferrer">§ 8 Absatz 5 APO-GOSt und VV 8.5</a>; auch anerkannte Feststellungsprüfungen können hierfür relevant sein.</li></ul><h2 id="zeugnisse-und-bescheinigungen" tabindex="-1">Zeugnisse und Bescheinigungen <a class="header-anchor" href="#zeugnisse-und-bescheinigungen" aria-label="Permalink to &quot;Zeugnisse und Bescheinigungen&quot;">​</a></h2><h3 id="zeugnisse-der-klassen-3-und-4-sowie-der-sekundarstufe-i" tabindex="-1">Zeugnisse der Klassen 3 und 4 sowie der Sekundarstufe I <a class="header-anchor" href="#zeugnisse-der-klassen-3-und-4-sowie-der-sekundarstufe-i" aria-label="Permalink to &quot;Zeugnisse der Klassen 3 und 4 sowie der Sekundarstufe I&quot;">​</a></h3><p>Die Schülerinnen und Schüler erhalten eine Bemerkung auf dem Zeugnis. Diese kann als Floskel unter <em>Kataloge</em> ➜ <strong>&quot;Floskeln&quot; bearbeiten</strong> unter der <em>Floskelgruppe</em> <strong>Zeugnisbemerkungen</strong> angelegt werden:</p><pre><code> &quot;$Vorname$ $Nachname$ hat am Unterricht in HERKUNFTSPRACHE teilgenommen. Die Leistungen werden mit LEISTUNGSNOTE bewertet.&quot;
</code></pre><p>Die <strong>Herkunftssprache</strong> und die <strong>Note</strong> müssen in der Floskel entsprechend eingetragen werden.</p><p>In den <strong>Zeugnissen der Schuleingangsphase der Grundschule</strong> wird statt der Leistungsnote eine Aussage über die Lernentwicklung im Herkunftssprachlichen Unterricht unter <strong>&quot;Hinweise zu den Lernbereichen/Fächern&quot;</strong> aufgenommen.</p><p>Dies gilt auch für Klasse 3, wenn die Schulkonferenz beschließt, im Zeugnis der Klasse 3 oder im Versetzungszeugnis der Klasse 3 auf Noten zu verzichten.</p><p>In Klasse 4 wird eine Leistungsnote erteilt.</p><h3 id="zeugnis-abschlusszeugnisse-der-sekundarstufe-i" tabindex="-1">Zeugnis: Abschlusszeugnisse der Sekundarstufe I <a class="header-anchor" href="#zeugnis-abschlusszeugnisse-der-sekundarstufe-i" aria-label="Permalink to &quot;Zeugnis: Abschlusszeugnisse der Sekundarstufe I&quot;">​</a></h3><p>Die Note wird im Abschlusszeugnis Ende der Sekundarstufe I im Prüfungsjahr, oder zeitverzögert in der Sekundarstufe II unter „Leistungen“ bescheinigt. Unter „Bemerkungen“ wird angegeben, dass die Note auf einer Sprachprüfung nach der Teilnahme am Herkunftssprachlichen Unterricht beruht und auf welcher Anspruchshöhe die Sprachprüfung abgelegt wurde.</p><p>Sofern die Sprachprüfung nicht bestanden wurde, wird eine Bescheinigung über die Teilnahme am Unterricht ausgestellt. Als Bemerkung kann folgende Floskel angelegt werden:</p><pre><code> &quot;Die Note im Fach HERKUNFTSPRACHE beruht auf einer Sprachenprüfung nach der Teilnahme am Herkunftssprachlichen Unterricht und wurde auf der Anspruchshöhe ANSPRUCHSHÖHE abgelegt.&quot;
</code></pre><p>Die Herkunftssprache und die Anspruchshöhe (ESA, EESA und MSA) muss in der Floskel entsprechend eingetragen werden.</p><h3 id="zeugnis-abiturzeugnis-und-abgangszeugnisse-der-sekundarstufe-ii" tabindex="-1">Zeugnis: Abiturzeugnis und Abgangszeugnisse der Sekundarstufe II <a class="header-anchor" href="#zeugnis-abiturzeugnis-und-abgangszeugnisse-der-sekundarstufe-ii" aria-label="Permalink to &quot;Zeugnis: Abiturzeugnis und Abgangszeugnisse der Sekundarstufe II&quot;">​</a></h3><p>Für Abitur- und Abgangszeugnisse der Sekundarstufe II sind die einschlägigen Zeugnisvorgaben und der konkrete Sprachnachweis maßgeblich. Tragen Sie ein GeR-Niveau nur ein, wenn es belegt ist; die HSU-Prüfungsnote allein begründet keine pauschale B1-Eintragung. Die folgende Bemerkung kann einen entsprechenden Nachweis erläutern:</p><pre><code> &quot;Das für HERKUNFTSPRACHE ausgewiesene Niveau wurde durch eine Sprachprüfung nach der Teilnahme am Herkunftssprachlichen Unterricht erreicht.“&quot;
</code></pre><h3 id="bescheinigung" tabindex="-1">Bescheinigung <a class="header-anchor" href="#bescheinigung" aria-label="Permalink to &quot;Bescheinigung&quot;">​</a></h3><p>Die Teilnahme am Unterricht in der Herkunftsprache wird zusätzlich gemäß Anlage BASS 13-61 Nr. 2 bescheinigt.</p><h2 id="einstellungen-in-schild-nrw" tabindex="-1">Einstellungen in SchILD-NRW <a class="header-anchor" href="#einstellungen-in-schild-nrw" aria-label="Permalink to &quot;Einstellungen in SchILD-NRW&quot;">​</a></h2><h3 id="unterrichtsfacher" tabindex="-1">Unterrichtsfächer <a class="header-anchor" href="#unterrichtsfacher" aria-label="Permalink to &quot;Unterrichtsfächer&quot;">​</a></h3><p><a href="/bilder/unterricht-kataloge/tutorials-hsu-fach-anlegenpng.png"><img src="`+u+'" alt="Unterrichtsfach für Herkunftssprachlichen Unterricht (HSU) anlegen." loading="lazy"></a></p><p><em>Unterrichtsfach für Herkunftssprachlichen Unterricht (HSU) anlegen.</em></p><p>Legen Sie ein Fach für die Prüfungssprache unter <em>Kataloge</em> ➜ <strong>Unterrichtsfächer</strong> an. Hier wird die Sprache als Beispiel verwendet.</p><ul><li><strong>ASD-Bezeichnung</strong>: Unterricht für Herkunftssprache - Spanisch</li><li><strong>internes Kürzel</strong>: HSU Spanisch</li><li><strong>Bezeichnung</strong>: HSU Spanisch</li><li><strong>Bereich auf dem Zeugnis</strong>: Fremdsprachen</li><li><strong>Bezeichnung im Zeugnis</strong>: Spanisch</li><li><strong>Bezeichnung im Überweisungszeugnis</strong>: Spanisch</li><li>Sonstige Einstellungen, die anzuhaken sind: <strong>Fremdsprache</strong> unter Details und <strong>Auf Zeugnis</strong> und <strong>Sichtbar</strong> in der Fachübersichtsliste.</li></ul>',31),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),a("Hinweis")]),e("p",null,"Nach Anlegen des Faches sollte SchILD-NRW einmalig neu gestartet werden, damit die Kataloge vollständig neu eingelesen werden.")],-1),r('<h3 id="sprachenfolge-und-sprachprufungen" tabindex="-1">Sprachenfolge und Sprachprüfungen <a class="header-anchor" href="#sprachenfolge-und-sprachprufungen" aria-label="Permalink to &quot;Sprachenfolge und Sprachprüfungen&quot;">​</a></h3><p><a href="/bilder/unterricht-kataloge/tutorials-hsu-laufbahninfo.png"><img src="'+h+'" alt="Sprachenfolge für HSU" loading="lazy"></a></p><p><em>Sprachenfolge für HSU</em></p><p>Tragen Sie das Fach in die Sprachenfolge auf dem Reiter <em>Schüler</em> ➜ <strong>Laufbahninfo</strong> ein:</p><ul><li><strong>Fremdsprache</strong>: HSU Spanisch (hier im Screenshot SH)</li><li><strong>Reihenfolge</strong>: 2. Fremdsprache</li><li><strong>Referenzniveau</strong>: B1 (MSA)</li><li><strong>von Jahrgang/Abschnitt</strong>: leer lassen, ggf. mit der Taste <code>Entf.</code> leeren</li><li><strong>bis Jahrgang/Abschnitt</strong>: leer lassen, ggf. mit der Taste <code>Entf.</code> leeren</li></ul><p><strong>Sprachprüfungen</strong> Tragen Sie die <strong>Fremdsprache</strong> ein, die dem HSU entspricht und tragen Sie weiterhin die Daten der Prüfung ein und setzen Sie den Vorgaben entsprechende Haken und das Referenzniveau.</p><h3 id="leistungsdaten-fur-das-abschlusszeugnis-der-sekundarstufe-i" tabindex="-1">Leistungsdaten für das Abschlusszeugnis der Sekundarstufe I <a class="header-anchor" href="#leistungsdaten-fur-das-abschlusszeugnis-der-sekundarstufe-i" aria-label="Permalink to &quot;Leistungsdaten für das Abschlusszeugnis der Sekundarstufe I&quot;">​</a></h3><p><a href="/bilder/unterricht-kataloge/tutorials-hsu-leistungsdaten.png"><img src="'+g+`" alt="Leistungsdaten für HSU-Zeugnisdruck" loading="lazy"></a></p><p><em>Leistungsdaten für HSU-Zeugnisdruck</em></p><p>Fügen Sie den <strong>Leistungsdaten</strong> des Schülers im <em>aktuellen Abschnitt</em> ein Fach hinzu:</p><ul><li><strong>Fach</strong>: HSU Spanisch</li><li><strong>Auf Zeugnis</strong>: Aktiviert</li><li><strong>Kursart</strong>: leer</li><li><strong>Lehrkraft</strong>: leer</li><li><strong>Note</strong>: Prüfungsnote</li><li><strong>Wochenzeiteinheit</strong>: leer</li></ul><p>Setzen Sie auch eine <strong>Zeugnisbemerkung</strong>:</p><pre><code> &quot;Die Note im Fach HERKUNFTSPRACHE beruht auf einer Sprachenprüfung nach der Teilnahme am Herkunftssprachlichen Unterricht und wurde auf der Anspruchshöhe ANSPRUCHSHÖHE abgelegt.&quot;
</code></pre><h3 id="leistungsdaten-fur-abgangszeugnisse-und-das-abiturzeugnis" tabindex="-1">Leistungsdaten für Abgangszeugnisse und das Abiturzeugnis <a class="header-anchor" href="#leistungsdaten-fur-abgangszeugnisse-und-das-abiturzeugnis" aria-label="Permalink to &quot;Leistungsdaten für Abgangszeugnisse und das Abiturzeugnis&quot;">​</a></h3><p>Zeugnisbemerkung:</p><pre><code>  &quot;Das für HERKUNFTSPRACHE ausgewiesene Niveau wurde durch eine Sprachprüfung nach der Teilnahme am Herkunftssprachlichen Unterricht erreicht.&quot; 
</code></pre><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Herkunftssprachlicher_Unterricht_(Tutorial)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5776.</p>`,18)])])}const S=s(l,[["render",c]]);export{k as __pageData,S as default};
